import * as THREE from 'three/webgpu';
import { texture, uv, vec2 } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-journal-title';

  const rectW = 512, rectH = 320, atlasW = 512, atlasH = 320;
  const aspect = rectW / rectH;
  const height = 0.9;
  const width = height * aspect;

  const geometry = new THREE.PlaneGeometry(width, height);
  const material = new THREE.MeshBasicNodeMaterial({ transparent: true });

  const map = ctx.textureLoader.load(config.assets?.imageUrl || '/prism-mock/home/nodes/floating-accent.png');
  map.colorSpace = THREE.SRGBColorSpace;

  const offsetX = 0, offsetY = 0;
  const scaleX = rectW / atlasW, scaleY = rectH / atlasH;
  const uvNode = uv().mul(vec2(scaleX, scaleY)).add(vec2(offsetX, offsetY));
  material.map = map;
  material.colorNode = texture(map, uvNode);

  const plane = new THREE.Mesh(geometry, material);
  plane.name = 'journal-title-plane';
  group.add(plane);

  let textMesh = null;
  if (ctx.fontAtlas && ctx.fontAtlas.createText) {
    textMesh = ctx.fontAtlas.createText({
      text: 'Journal',
      font: 'display',
      weight: 400,
      size: 0.62,
      color: config.visual?.colors?.paper || '#e8ecf2',
      align: 'center',
    });
    textMesh.name = 'journal-title-text';
    textMesh.position.set(0, 0, 0.01);
    group.add(textMesh);
  }

  group.position.set(0, 3, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map && map.dispose) map.dispose();
    if (textMesh) {
      if (textMesh.geometry) textMesh.geometry.dispose();
      if (textMesh.material) textMesh.material.dispose();
    }
  };

  group.onBeforeRender = (renderer, scene, camera) => {
    group.quaternion.copy(camera.quaternion);
  };

  return group;
}
